<template>\n div class='modal' v-if='showModal'>\n   h2>{{ message }}</h2>\n   button @click='handleUpgrade'>Upgrade Now</button>\n div>\n</template>\n\n<script>\nimport { getConversionMessage } from '@/services/paywall_engine/messages';\n\nexport default {\n  data() {\n    return {\n      showModal: false,\n      message: ''\n    };\n  },\n  mounted() {\n    this.$eventHub.$on('showUpgradeModal', (triggerType) => {\n      this.message = getConversion_message(triggerType);\n      this.showModal = true;\n    });\n  },\n  methods: {\n    handleUpgrade() {\n      window.location.href = '/checkout';\n    }\n  }\n};\n</script>